// Lấy số lần tưới hiện tại.
// Nếu chưa có thì mặc định là 0.
let count = flow.get("wateringCount") || 0;

// Mỗi lần bấm inject giả lập, tăng số lần tưới lên 1.
count = count + 1;

// Lưu lại vào bộ nhớ flow của Node-RED.
flow.set("wateringCount", count);

// In nội dung ra debug để kiểm tra.
msg.payload = "Số lần tưới hôm nay: " + count;

return msg;

// Lấy số lần tưới đã lưu
let count = flow.get("wateringCount") || 0;

// Lấy thời gian hiện tại
let now = new Date();

let timeText = now.toLocaleString("vi-VN", {
    timeZone: "Asia/Ho_Chi_Minh"
});

// Email người nhận.
// Có thể đổi thành email của bạn.
msg.to = "bthloan2006@gmail.com";

// Tiêu đề email
msg.topic = "Báo cáo tưới nước hằng ngày - Vườn thông minh IoT";

// Nội dung email
msg.payload =
    `BÁO CÁO HỆ THỐNG VƯỜN THÔNG MINH IOT

Thời gian gửi báo cáo: ${timeText}

Hôm nay hệ thống đã kích hoạt tưới nước: ${count} lần.

Ghi chú:
- Đây là email báo cáo định kỳ hằng ngày.
- Chức năng này dùng riêng cho yêu cầu Email.
- Không dùng chung điều kiện với thông báo nhanh.

Trân trọng,
Hệ thống Vườn Thông Minh IoT`;

return msg;

// Sau khi gửi email báo cáo xong,
// reset số lần tưới về 0 để bắt đầu chu kỳ mới.
flow.set("wateringCount", 0);

msg.payload = "Đã gửi email và reset số lần tưới về 0.";

return msg;

const status = String(msg.payload || "")
    .trim()
    .toUpperCase();

if (status !== "ONLINE" && status !== "OFFLINE") {
    return null;
}

msg.payload = status;
return msg;

let NhietDo = Math.round(Math.random() * 20) + 20
let DoAm = Math.round(Math.random()) * 100 
let AnhSang = Math.round(Math.random() * 500) + 100

msg.payload = {
    "nhiet_do": NhietDo,
    "do_am": DoAm,
    "anh_sang": AnhSang
}

return msg;

let msg1 = { payload: msg.payload.nhiet_do };
let msg2 = { payload: msg.payload.do_am };
let msg3 = { payload: msg.payload.anh_sang };

return [msg1, msg2, msg3];
